function rateLimit({ tokens, refillPerSec }) {
  const buckets = new Map();
  return (req, res, next) => {
    const key = req.ip;
    const now = Date.now();
    const b = buckets.get(key) || { t: tokens, last: now };
    const elapsed = (now - b.last) / 1000;
    b.t = Math.min(tokens, b.t + elapsed * refillPerSec);
    b.last = now;
    if (b.t < 1) return res.status(429).end();
    b.t -= 1;
    buckets.set(key, b);
    next();
  };
}
```
