async function retry(fn, { attempts = 3, baseMs = 100 } = {}) {
  let last;
  for (let i = 0; i < attempts; i++) {
    try { return await fn(); } catch (e) {
      last = e;
      const wait = baseMs * 2 ** i + Math.random() * baseMs;
      await new Promise(r => setTimeout(r, wait));
    }
  }
  throw last;
}
```

