const idempotency = (redis) => async (req, res, next) => {
  const key = req.header('Idempotency-Key');
  if (!key) return next();
  const cached = await redis.get(`idemp:${key}`);
  if (cached) return res.status(200).json(JSON.parse(cached));
  const origJson = res.json.bind(res);
  res.json = (body) => {
    if (res.statusCode < 400) redis.set(`idemp:${key}`, JSON.stringify(body), 'EX', 86400);
    return origJson(body);
  };
  next();
};
```
Edge cases: partial writes if server crashes between op and cache set — mitigate with 2-phase key (reserve → complete).

