const { WebSocketServer } = require('ws');
const Redis = require('ioredis');
const pub = new Redis(), sub = new Redis();
const rooms = new Map(); // room -> Set<WebSocket>

function subscribe(ws, room) {
  if (!rooms.has(room)) rooms.set(room, new Set());
  rooms.get(room).add(ws);
  ws.on('close', () => rooms.get(room)?.delete(ws));
}

async function broadcast(room, message) {
  await pub.publish(`room:${room}`, JSON.stringify(message));
}

sub.psubscribe('room:*');
sub.on('pmessage', (_pat, channel, msg) => {
  const room = channel.slice(5);
  const set = rooms.get(room);
  if (!set) return;
  for (const ws of set) if (ws.readyState === ws.OPEN) ws.send(msg);
});
```
Every node subscribes to Redis; broadcasts fan out to whichever nodes hold sockets in that room.

